function parseMail($json) {
const subject = $json.subject || '';
const body = $json.body?.content || '';
const preview = $json.bodyPreview || '';
const from = $json.from || '';

const texto = `${subject}\n${body}\n${preview}`;

const textoLimpo = texto
  .replace(/<[^>]*>/g, ' ').replace(/&nbsp;|&#160;/gi,' ').replace(/&amp;/gi,'&').replace(/\[([^\]]+)\]\([^)]*\)/g,'$1').replace(/\*\*/g,'')
  .replace(/\s+/g, ' ')
  .trim();

// MOTIVO DA NEGACAO
const motivoNegacaoRaw =
  texto.match(/Motivo da nega[cç][aã]o\s*:?\s*(.*?)(?=Detalhes da nega[cç][aã]o|Nome da Conta do Parceiro|Deal Type|Total Expected Revenue|$)/is)?.[1] ||
  texto.match(/Reason for rejection\s*:?\s*(.*?)(?=Rejection details|Partner Account Name|Deal Type|Total Expected Revenue|$)/is)?.[1] ||
  '';

const motivoNegacao = motivoNegacaoRaw
  .replace(/\s+/g, ' ')
  .replace(/<[^>]*>/g,' ').replace(/^[:\s]*/, '')
  .trim();


function extract(regex) {
  const match = textoLimpo.match(regex);
  return match ? match[1].trim() : '';
}

function normalizar(texto) {
  return (texto || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

// STATUS
const subjectLower = subject.toLowerCase();

let status = 'Não identificado';

if (
  subjectLower.includes('rejeitada') ||
  subjectLower.includes('rejected')
) {
  status = 'Rejeitada';
} else if (
  subjectLower.includes('approved deal is about to expire') ||
  subjectLower.includes('about to expire') ||
  subjectLower.includes('expire')
) {
  status = 'Expirando';
} else if (/renovad[ao]|renova[çc][aã]o|renewed|renewal/i.test(subject)) {
  status = 'Renovada';
} else if (
  subjectLower.includes('oportunidade atualizada') ||
  subjectLower.includes('updated')
) {
  status = 'Atualizada';
} else if (
  subjectLower.includes('aprovada') ||
  subjectLower.includes('approved')
) {
  status = 'Aprovada';
}


// R.O
const numeroOportunidade =
  extract(/n[uú]mero da oportunidade[:\s]*([0-9]+)/i) ||
  extract(/Deal ID[:\s]*([0-9]+)/i);

// NOME DA OPORTUNIDADE / RAZÃO SOCIAL
const nomeOportunidade =
  extract(/Opportunity Name[:\s]*(.*?)(?=\s+Partner Program Track|\s+Plano do|\s+Plan|\s+Deal|\s*$)/i) ||
  extract(/Nome da oportunidade[:\s]*(.*?)(?=\s+Partner Program Track|\s+Plano do|\s+Plan|\s+Deal|\s*$)/i) ||
  '';

const partesNome = nomeOportunidade.split('|').map(p => p.trim());
const razaoSocial = partesNome[0] || '';

// CÓDIGO DE REFERÊNCIA DE RENOVAÇÃO (REF)
// Ao renovar um R.O já existente, o vendedor inclui no "Opportunity Name" do portal Dell
// o texto REF:<numero do R.O atual no CRM>. Ex: CLIENTE | Vendedor | 03x R660 REF:32081947
const roReferencia = nomeOportunidade.match(/\bREF\s*[:\-]?\s*([0-9]{5,})/i)?.[1] || '';
const isRenovacaoExplicita = !!roReferencia && roReferencia !== numeroOportunidade;

// VENDEDORES
const mapaVendedores = {
  "Ana Souza": { id: 101, email: "ana.souza@empresa.example" },
  "Bruno Lima": { id: 102, email: "bruno.lima@empresa.example" },
  "Carla Mendes": { id: 103, email: "carla.mendes@empresa.example" }
};

const textoNormalizado = normalizar(`${nomeOportunidade} ${subject}`);

let nomeVendedor = '';

const nomesOrdenados = Object.keys(mapaVendedores).sort((a, b) => b.length - a.length);

for (const nome of nomesOrdenados) {
  const nomeNormalizado = normalizar(nome);
  const regex = new RegExp(`\\b${nomeNormalizado}\\b`);

  if (regex.test(textoNormalizado)) {
    nomeVendedor = nome;
    break;
  }
}

if (!nomeVendedor) {
  nomeVendedor = 'Ana Souza'; // vendedor padrão quando nenhum nome é identificado
}

const vendedor = mapaVendedores[nomeVendedor];
const vendedorId = vendedor.id;
const vendedorEmail = vendedor.email;

const nomeCliente = `${razaoSocial} | ${nomeVendedor} | R.O ${numeroOportunidade}`;

// RECEITA USD → BRL
const valorDolarTexto =
  textoLimpo.match(/Total\s*Expected\s*Revenue[:\s]*([0-9.,]+)/i)?.[1] || '';

const valorDolar = valorDolarTexto
  ? Number(valorDolarTexto.replace(',', '.'))
  : 0;

const cotacaoDolar = 5.20;
const expectedRevenue = Number((valorDolar * cotacaoDolar).toFixed(2));

// LOB
const produtosCSG = [
  'Dell Pro',
  'Latitude',
  'Accessories',
  'Dell Tower',
  'Monitor',
  'Ultrasharp',
  'Dell 22',
  'Dell 24',
  'Dell'
];

const produtosISG = [
  'PowerEdge',
  'PowerVault',
  'Networking',
  'PowerStore',
  'E3248P',
  'R',
  'ME',
  'APC',
  'XE',
  'Z-Series',
  'PowerScale',
  'Unity'
];

const textoProdutos = nomeOportunidade.toLowerCase();

const encontrouISG = /\b(poweredge|powervault|powerstore|powerscale|unity|networking|r\d{3,4}|xe\d{3,4}|me\d{3,4})\b/i.test(textoProdutos);
const encontrouCSG = /\b(dell pro|latitude|precision|optiplex|alienware|vostro|inspiron|monitor|ultrasharp|notebook|desktop|csg)\b/i.test(textoProdutos);
let lob = encontrouISG ? 'ISG-Storage,Server,Network' : encontrouCSG ? 'CSG-Notebook,Desktops' : '';
// DATA EXPIRAÇÃO
const dataExpiracaoTexto =
  extract(/Deal Expiration Date[:\s]*(\d{1,2}\/\d{1,2}\/\d{4})/i) ||
  extract(/Deal Expiration Date[:\s]*([A-Za-z]{3}\s+[A-Za-z]{3}\s+\d{1,2}\s+\d{2}:\d{2}:\d{2}\s+GMT\s+\d{4})/i) ||
  extract(/Data de expira[çc][aã]o do Registro de Oportunidade[:\s]*([A-Za-z]{3}\s+[A-Za-z]{3}\s+\d{1,2}\s+\d{2}:\d{2}:\d{2}\s+GMT\s+\d{4})/i);

function formatarDataOdoo(dataTexto) {
  if (!dataTexto) return false;

  const data = new Date(dataTexto);

  if (isNaN(data.getTime())) return false;

  return data.toISOString().slice(0, 10);
}

const dataExpiracaoOdoo = formatarDataOdoo(dataExpiracaoTexto);

// MARCADOR GOVERNO / EMPRESA PRIVADA
const razaoSocialNormalizada = normalizar(razaoSocial);

const nomesPessoas = [
  'ana', 'bruno', 'carla'
];

const termosGoverno = [
  'fapesp',
  'funcate',
  'funcamp',
  'organizacao',
  'sesi',
  'senar',

];

const termosEmpresaPrivada = [
  'ltda',
  'me',
  'sa',
  's.a',
  'epp',
  'ind',
  'grupo'
];

const iniciaComNomePessoa = nomesPessoas.some(nome =>
  razaoSocialNormalizada.startsWith(nome)
);

const contemTermoGoverno = termosGoverno.some(termo =>
  razaoSocialNormalizada.includes(termo)
);

const contemTermoEmpresaPrivada = termosEmpresaPrivada.some(termo =>
  razaoSocialNormalizada.includes(termo)
);

let marcadorCliente = 'Empresa Privada';

if (contemTermoGoverno || iniciaComNomePessoa) {
  marcadorCliente = 'Governo';
} else if (contemTermoEmpresaPrivada) {
  marcadorCliente = 'Empresa Privada';
}

const cicloMaximoRenovacao = marcadorCliente === 'Governo' ? 999 : 2;

// TROQUE PELOS IDS REAIS DAS TAGS NO ODOO
const tagIdGoverno = 1;
const tagIdEmpresaPrivada = 2;

const tagId = marcadorCliente === 'Governo'
  ? tagIdGoverno
  : tagIdEmpresaPrivada;

if (!numeroOportunidade || status === 'Não identificado') return [];
const numeroRoAnterior = extract(/(?:R\.?O\.? anterior|Previous Deal ID)[:\s]*([0-9]+)/i);
// FLAGS PARA IF
const isCriar = status === 'Aprovada' || status === 'Renovada';
const isAtualizar = status === 'Atualizada' || status === 'Expirando';
const isRejeitada = status === 'Rejeitada';

return [
  {
    json: {
      numeroRoAnterior,
      descricao: textoLimpo,
      messageId: $json.id,
      conversationId: $json.conversationId,
      subject,
      from,
      bodyPreview: preview,
      status,
      isCriar,
      isAtualizar,
      isRejeitada,
      numeroOportunidade,
      nomeOportunidade,
      roReferencia,
      isRenovacaoExplicita,
      razaoSocial,
      nomeCliente,
      nomeVendedor,
      vendedorId,
      vendedorEmail,
      valorDolarTexto,
      valorDolar,
      cotacaoDolar,
      expectedRevenue,
      lob,
      dataExpiracaoTexto,
      dataExpiracaoOdoo,
      marcadorCliente,
      cicloMaximoRenovacao,
      tagId,
      motivoNegacao,

    }
  }
];
}
const itens = $input.all().flatMap((item,index)=>parseMail(item.json).map(out=>({...out,pairedItem:{item:index}})));

// DEDUPLICAÇÃO NO LOTE: se chegarem 2+ e-mails do mesmo R.O na mesma execução,
// processa apenas um (prioriza o de criação) para não criar oportunidades duplicadas.
const porRo = new Map();
for (const it of itens) {
  const atual = porRo.get(it.json.numeroOportunidade);
  if (!atual || (!atual.json.isCriar && it.json.isCriar)) porRo.set(it.json.numeroOportunidade, it);
}
return [...porRo.values()];
